// #Sireum

package eit_acquisition_supervisor.EIT_Acquisition_Supervisor

import org.sireum._
import art.Art
import eit_acquisition_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait RecoveryControl_acquisition_process_recovery_control_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control)
  }

  /** helper function to set the values of all input ports.
   * @param recovery_event payload for data port recovery_event
   * @param fault_summary payload for data port fault_summary
   */
  def put_concrete_inputs(recovery_event : EIT_Acquisition_Supervisor.RecoveryEvent.Type,
                          fault_summary : EIT_Acquisition_Supervisor.FaultSummary): Unit = {
    put_recovery_event(recovery_event)
    put_fault_summary(fault_summary)
  }


  /** helper function to check RecoveryControl_acquisition_process_recovery_control's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recovery_frame method that will be called with the value of the outgoing data
   *        port 'recovery_frame'.
   */
  def check_concrete_output(recovery_frame: EIT_Acquisition_Supervisor.RecoveryFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recovery_frameValue: EIT_Acquisition_Supervisor.RecoveryFrame = get_recovery_frame().get
    if(!recovery_frame(recovery_frameValue)) {
      testFailures = testFailures :+ st"'recovery_frame' did not match expected: value of the outgoing data port is ${recovery_frameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recovery_event(value : EIT_Acquisition_Supervisor.RecoveryEvent.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.operational_api.recovery_event_Id, EIT_Acquisition_Supervisor.RecoveryEvent_Payload(value))
  }

  // setter for in DataPort
  def put_fault_summary(value : EIT_Acquisition_Supervisor.FaultSummary): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.operational_api.fault_summary_Id, EIT_Acquisition_Supervisor.FaultSummary_Payload(value))
  }

  // getter for out DataPort
  def get_recovery_frame(): Option[EIT_Acquisition_Supervisor.RecoveryFrame] = {
    val value: Option[EIT_Acquisition_Supervisor.RecoveryFrame] = get_recovery_frame_payload() match {
      case Some(EIT_Acquisition_Supervisor.RecoveryFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port recovery_frame.  Expecting 'EIT_Acquisition_Supervisor.RecoveryFrame_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.RecoveryFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_recovery_frame_payload(): Option[EIT_Acquisition_Supervisor.RecoveryFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.initialization_api.recovery_frame_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.RecoveryFrame_Payload]]
  }

}
